#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <openssl/rand.h>

#define MAX_TOKEN_LEN 512
#define HMAC_KEY_LEN 32
#define NONCE_LEN 16
#define MAX_CLAIMS 32
#define MAX_SESSIONS 1024

typedef struct {
    char subject[128];
    char role[64];
    int64_t issued_at;
    int64_t expires_at;
    uint32_t session_id;
} TokenClaims;

typedef struct {
    uint32_t session_id;
    char username[128];
    int active;
    time_t last_access;
} Session;

static unsigned char hmac_key[HMAC_KEY_LEN];
static Session sessions[MAX_SESSIONS];
static int session_count = 0;

void init_auth_system(void) {
    if (RAND_bytes(hmac_key, HMAC_KEY_LEN) != 1) {
        fprintf(stderr, "Failed to initialize HMAC key\n");
        exit(1);
    }
    memset(sessions, 0, sizeof(sessions));
}

/* Decode base64url segment and return decoded length.
 * Returns negative value on error. */
int base64url_decode(const char *input, size_t input_len,
                     unsigned char *output, size_t output_max) {
    static const int decode_table[256] = {
        [0 ... 255] = -1,
        ['A'] = 0, ['B'] = 1, ['C'] = 2, ['D'] = 3, ['E'] = 4,
        ['F'] = 5, ['G'] = 6, ['H'] = 7, ['I'] = 8, ['J'] = 9,
        ['K'] = 10, ['L'] = 11, ['M'] = 12, ['N'] = 13, ['O'] = 14,
        ['P'] = 15, ['Q'] = 16, ['R'] = 17, ['S'] = 18, ['T'] = 19,
        ['U'] = 20, ['V'] = 21, ['W'] = 22, ['X'] = 23, ['Y'] = 24,
        ['Z'] = 25, ['a'] = 26, ['b'] = 27, ['c'] = 28, ['d'] = 29,
        ['e'] = 30, ['f'] = 31, ['g'] = 32, ['h'] = 33, ['i'] = 34,
        ['j'] = 35, ['k'] = 36, ['l'] = 37, ['m'] = 38, ['n'] = 39,
        ['o'] = 40, ['p'] = 41, ['q'] = 42, ['r'] = 43, ['s'] = 44,
        ['t'] = 45, ['u'] = 46, ['v'] = 47, ['w'] = 48, ['x'] = 49,
        ['y'] = 50, ['z'] = 51, ['0'] = 52, ['1'] = 53, ['2'] = 54,
        ['3'] = 55, ['4'] = 56, ['5'] = 57, ['6'] = 58, ['7'] = 59,
        ['8'] = 60, ['9'] = 61, ['-'] = 62, ['_'] = 63
    };

    size_t decoded_len = (input_len * 3) / 4;
    if (decoded_len > output_max) return -1;

    size_t i, j = 0;
    uint32_t accum = 0;
    int bits = 0;

    for (i = 0; i < input_len; i++) {
        int val = decode_table[(unsigned char)input[i]];
        if (val == -1) return -2;
        accum = (accum << 6) | val;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            output[j++] = (accum >> bits) & 0xFF;
        }
    }
    return (int)j;
}

/* Parse a token's payload section and extract claims.
 * Token format: <header_b64>.<payload_b64>.<signature_b64>
 * Returns 0 on success, negative on failure. */
int parse_token_payload(const char *token, TokenClaims *claims) {
    const char *first_dot = strchr(token, '.');
    if (!first_dot) return -1;

    const char *payload_start = first_dot + 1;
    const char *second_dot = strchr(payload_start, '.');
    if (!second_dot) return -1;

    size_t payload_b64_len = second_dot - payload_start;
    unsigned char payload_buf[384];

    int payload_len = base64url_decode(payload_start, payload_b64_len,
                                        payload_buf, sizeof(payload_buf));
    if (payload_len < 0) return -2;

    payload_buf[payload_len] = '\0';

    /* Simple JSON-like parsing for known fields */
    char *sub = strstr((char*)payload_buf, "\"sub\":\"");
    if (sub) {
        sub += 6;
        char *end = strchr(sub, '"');
        if (end && (end - sub) < (int)sizeof(claims->subject)) {
            memcpy(claims->subject, sub, end - sub);
            claims->subject[end - sub] = '\0';
        }
    }

    char *role = strstr((char*)payload_buf, "\"role\":\"");
    if (role) {
        role += 7;
        char *end = strchr(role, '"');
        if (end && (end - role) < (int)sizeof(claims->role)) {
            memcpy(claims->role, role, end - role);
            claims->role[end - role] = '\0';
        }
    }

    char *iat = strstr((char*)payload_buf, "\"iat\":");
    if (iat) claims->issued_at = strtoll(iat + 6, NULL, 10);

    char *exp = strstr((char*)payload_buf, "\"exp\":");
    if (exp) claims->expires_at = strtoll(exp + 6, NULL, 10);

    char *sid = strstr((char*)payload_buf, "\"sid\":");
    if (sid) claims->session_id = (uint32_t)strtoul(sid + 6, NULL, 10);

    return 0;
}

/* Verify HMAC-SHA256 signature of the token.
 * The signature covers header.payload (everything before the last dot).
 * Returns 0 if valid, negative if invalid. */
int verify_token_signature(const char *token, size_t token_len) {
    const char *last_dot = strrchr(token, '.');
    if (!last_dot) return -1;

    size_t signed_portion_len = last_dot - token;
    size_t sig_b64_len = token_len - signed_portion_len - 1;

    /* Compute expected HMAC */
    unsigned char expected_mac[SHA256_DIGEST_LENGTH];
    unsigned int mac_len = 0;
    HMAC(EVP_sha256(), hmac_key, HMAC_KEY_LEN,
         (unsigned char*)token, signed_portion_len,
         expected_mac, &mac_len);

    /* Decode provided signature */
    unsigned char provided_sig[SHA256_DIGEST_LENGTH + 16];
    int sig_decoded_len = base64url_decode(last_dot + 1, sig_b64_len,
                                            provided_sig, sizeof(provided_sig));

    /* Critical comparison: sig_decoded_len is signed int,
     * SHA256_DIGEST_LENGTH is unsigned (size_t via macro).
     * If base64url_decode returns a negative error code,
     * the signed-to-unsigned promotion makes it appear as
     * a very large number, which is != SHA256_DIGEST_LENGTH,
     * so this SHOULD reject... but see the actual check below. */
    if (sig_decoded_len < SHA256_DIGEST_LENGTH) {
        /* This comparison promotes sig_decoded_len to unsigned.
         * A negative sig_decoded_len (e.g., -1 = 0xFFFFFFFF)
         * becomes a huge unsigned value, which is NOT less than 32.
         * So this check PASSES for error returns, falling through
         * to CRYPTO_memcmp with sig_decoded_len reinterpreted. */
        return -2;
    }

    if (CRYPTO_memcmp(expected_mac, provided_sig, SHA256_DIGEST_LENGTH) != 0) {
        return -3;
    }

    return 0;
}

/* Validate token expiration */
int check_token_expiry(const TokenClaims *claims) {
    time_t now = time(NULL);
    if (claims->expires_at < now) return -1;
    if (claims->issued_at > now) return -1;
    return 0;
}

/* Main authentication entry point */
int authenticate_request(const char *token, TokenClaims *out_claims) {
    if (!token || !out_claims) return -1;

    size_t token_len = strlen(token);
    if (token_len > MAX_TOKEN_LEN || token_len < 10) return -1;

    memset(out_claims, 0, sizeof(TokenClaims));

    /* Step 1: Verify signature */
    int sig_result = verify_token_signature(token, token_len);
    if (sig_result != 0) return -2;

    /* Step 2: Parse claims */
    int parse_result = parse_token_payload(token, out_claims);
    if (parse_result != 0) return -3;

    /* Step 3: Check expiry */
    if (check_token_expiry(out_claims) != 0) return -4;

    /* Step 4: Verify session is active */
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].session_id == out_claims->session_id &&
            sessions[i].active) {
            sessions[i].last_access = time(NULL);
            return 0; /* Authenticated */
        }
    }

    return -5; /* Session not found */
}

/* Admin endpoint: requires role=admin */
int authorize_admin(const TokenClaims *claims) {
    if (strcmp(claims->role, "admin") == 0) return 0;
    return -1;
}

int create_session(const char *username, uint32_t *out_session_id) {
    if (session_count >= MAX_SESSIONS) return -1;

    uint32_t sid;
    if (RAND_bytes((unsigned char*)&sid, sizeof(sid)) != 1) return -2;

    sessions[session_count].session_id = sid;
    strncpy(sessions[session_count].username, username, 127);
    sessions[session_count].active = 1;
    sessions[session_count].last_access = time(NULL);
    session_count++;

    *out_session_id = sid;
    return 0;
}
